"use strict";(globalThis.webpackChunkmy_website||=[]).push([[36880],{85358(e){e.exports=JSON.parse('{"slug":"ispo","title":"ISPO","short":"A fundraising method where supporters delegate ada to a designated stake pool and receive the project\'s tokens in lieu of staking rewards; participants keep custody of their ada throughout.","category":"consensus","aliases":["Initial Stake Pool Offering"],"mentalModel":null,"related":["stake-pool","delegation"],"sources":[],"link":null,"level":"intermediate","body":"Because no ada ever leaves the delegator\'s wallet, ISPOs avoid the custody risk of traditional token sales: the only thing at stake is the staking yield the participant chooses to redirect."}')}}]);